// Confere a lista de leads que o sistema mandou.
const entrada = items[0].json;
const corpo = entrada.body || {};
const formatoId = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Lista de leads: só IDs válidos e sem repetir.
const ids = [...new Set(
  (Array.isArray(corpo.lead_ids) ? corpo.lead_ids : [])
    .filter((id) => typeof id === "string" && formatoId.test(id))
)];

if (!ids.length) {
  throw new Error("Pedido sem leads válidos.");
}

// Quem aprovou (e-mail do usuário no sistema).
const aprovadoPor = String(corpo.aprovado_por || "desconhecido").slice(0, 200);

return [{ json: { ids_pg: `{${ids.join(",")}}`, aprovado_por: aprovadoPor, total_pedido: ids.length } }];

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

// WhatsApp da IA da Monteiro (DDD 85), número fixo — não é o telefone do lead.
const WHATSAPP_MONTEIRO = '558523980088';
const LOGO_URL = 'https://monteiro-adv.lovable.app/__l5e/assets-v1/fad5f220-ce6d-44d4-9777-d0e0572d470f/monteiro-ramalho-logo-white.png';

const empresa  = $json.empresa;
const email    = $json.email;
const corpo    = $('Montar Body da Requisição WhatsApp').first().json.mensagem_completa;

const subject = `Oportunidade de recuperação de créditos tributários — ${empresa}`;

const paragrafos = String(corpo || '')
  .split(/\n\s*\n/)
  .map((p) => p.trim())
  .filter(Boolean)
  .map((p) => `<p style="margin:0 0 16px 0;font-family:Georgia,'Times New Roman',serif;font-size:14px;line-height:1.7;color:#1a2030;">${esc(p).replace(/\n/g, '<br/>')}</p>`)
  .join('');

// Botão de WhatsApp: sempre aparece, aponta pro WhatsApp da IA da Monteiro.
const botaoWhatsapp = `
  <div style="text-align:center;margin:8px 0 8px 0;">
    <a href="https://wa.me/${WHATSAPP_MONTEIRO}" style="display:inline-block;background:#25D366;color:#ffffff;text-decoration:none;padding:14px 28px;border-radius:4px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:600;letter-spacing:0.04em;">Falar no WhatsApp</a>
  </div>
`;

const html = `<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Monteiro Ramalho — ${esc(empresa)}</title>
</head>
<body style="margin:0;padding:0;background:#f5f3ee;font-family:Georgia,'Times New Roman',serif;color:#1a2030;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f5f3ee;padding:32px 12px;">
    <tr><td align="center">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #e5e0d6;border-radius:6px;overflow:hidden;">

        <tr><td style="background:#0d2a4a;padding:28px 32px;text-align:center;">
          <img src="${LOGO_URL}" alt="Monteiro Ramalho Advogados Associados" width="172" height="37" style="display:block;margin:0 auto 12px auto;border:0;max-width:172px;height:auto;" />
          <div style="font-family:Georgia,'Times New Roman',serif;color:#ffffff;font-size:20px;letter-spacing:0.08em;font-weight:600;">MONTEIRO RAMALHO</div>
          <div style="margin-top:4px;font-family:Arial,Helvetica,sans-serif;color:#c9a84c;font-size:10px;letter-spacing:0.3em;text-transform:uppercase;">Advogados Associados</div>
        </td></tr>
        <tr><td style="height:3px;background:#c9a84c;"></td></tr>

        <tr><td style="padding:36px 32px 8px 32px;">
          ${paragrafos}
          ${botaoWhatsapp}
        </td></tr>

        <tr><td style="border-top:1px solid #e5e0d6;"></td></tr>
        <tr><td style="padding:20px 32px;background:#fafaf7;text-align:center;">
          <p style="margin:0;font-family:Georgia,'Times New Roman',serif;font-size:13px;color:#0d2a4a;font-weight:600;">Monteiro Ramalho Advogados Associados</p>
        </td></tr>

      </table>
    </td></tr>
  </table>
</body>
</html>`;

return [{ json: { ...$json, subject, html } }];

